// AWI: label "TBA" di tombol Harga Mulai halaman BYD TiTAN 7 DM (harga resmi belum keluar).
// Hapus/nonaktifkan snippet ini setelah harga OTR diisi di field tipe & harga model.
add_action('wp_head', function () {
	if (!is_single(10706)) return;
	echo '<style id="awi-titan-tba">.model__price>div::after{content:" TBA";font-weight:800;letter-spacing:1px;margin-left:4px}</style>';
}, 99);
